-- Flyway Migration: V11 — Topic Templates Table
-- Static seed table of 19 ESG topic templates with pre-defined instructions.
-- Used by the frontend to pre-populate topics when a new project is created.
-- This table is read-only at runtime; all 19 rows are inserted here.

SET search_path TO vdr_agent, public;

CREATE TABLE IF NOT EXISTS topic_templates (
    id         INTEGER PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    instruction TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

COMMENT ON TABLE topic_templates IS 'Read-only seed table of 19 ESG due-diligence topic templates with pre-defined instructions';
COMMENT ON COLUMN topic_templates.id IS 'Stable 1-19 ordinal matching the ESG topic order in the source document';
COMMENT ON COLUMN topic_templates.name IS 'ESG topic name, e.g. "ESG Strategy", "Health and Safety Management"';
COMMENT ON COLUMN topic_templates.instruction IS 'Pre-defined instruction text for AI categorisation — editable per project via vdr_agent.topics';

ON CONFLICT (id) DO NOTHING;
